NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Revelation of John'

CHAPTERS = {
    1: {
        1: 'Jeesuksen Kristuksen ilmoitus, jonka Jumala antoi hänelle näyttääkseen palvelijoilleen, mitä pitää pian tapahtua, ja minkä hän lähettämänsä enkelin kautta ilmoitti näkyinä palvelijalleen Johannekselle.',
        2: 'Hän on todistanut tässä Jumalan sanan ja Jeesuksen Kristuksen todistuksen, kaiken sen, minkä hän näki.',
        3: 'Autuas se, joka lukee, ja autuaat ne, jotka kuulevat tämän profetian sanat ja pitävät sen, mitä siihen on kirjoitettu, sillä aika on lähellä!',
        4: 'Johannes seitsemälle Aasian maakunnan seurakunnalle: Armo teille ja rauha häneltä, joka on ja joka oli ja joka tuleva on, ja niiltä seitsemältä hengeltä, jotka ovat hänen valtaistuimensa edessä,',
        5: 'ja Jeesukselta Kristukselta, uskolliselta todistajalta, häneltä, joka on kuolleitten esikoinen ja maan kuningasten hallitsija! Hänelle, joka meitä rakastaa ja on pessyt meidät synneistämme verellään',
        6: 'ja tehnyt meidät kuninkaiksi, papeiksi Jumalalleen ja Isälleen, hänelle [olkoon] kunnia ja voima aina ja iäisyyksien iäisyyksiin! Aamen.',
        7: 'Katso, hän tulee pilvissä, ja jokainen silmä tulee näkemään hänet, nekin, jotka hänet lävistivät, ja kaikki maan sukukunnat vaikeroivat hänen tullessaan. Totisesti, aamen.',
        8: '"Minä olen A ja O", alku ja loppu, sanoo Herra Jumala, joka on ja joka oli ja joka tuleva on, Kaikkivaltias.',
        9: 'Minä, Johannes, teidän veljenne, joka olen kanssanne osallinen ahdistukseen, valtakuntaan ja Jeesuksen Kristuksen kärsivällisyyteen, olin Jumalan sanan ja Jeesuksen todistuksen tähden saaressa, jonka nimi on Patmos.',
        10: 'Olin Hengessä Herran päivänä, ja kuulin takaani suuren äänen, kuin torven äänen,',
        11: 'joka sanoi: "Minä olen A ja O, ensimmäinen ja viimeinen. Kirjoita kirjakääröön, mitä näet, ja lähetä niille seitsemälle seurakunnalle Aasian maakunnassa, Efesoon, Smyrnaan, Pergamoon, Tyatiraan, Sardeeseen, Filadelfiaan ja Laodikeaan."',
        12: 'Käännyin katsomaan kohti ääntä, joka puhui kanssani, ja kääntyessäni näin seitsemän kultaista lampunjalkaa,',
        13: 'ja seitsemän lampunjalan keskellä Ihmisen Pojan muotoisen, pitkäliepeiseen viittaan puetun ja rinnan kohdalta kultaisella vyöllä vyötetyn.',
        14: 'Hänen päänsä ja hiuksensa olivat valkoiset kuin valkoinen villa, kuin lumi, ja hänen silmänsä kuin tulen liekki.',
        15: 'Hänen jalkansa olivat ahjossa tulella puhdistetun, sulan vasken kaltaiset, ja hänen äänensä oli kuin paljojen vetten ääni.',
        16: 'Hänellä oli oikeassa kädessään seitsemän tähteä, ja hänen suustaan lähti kaksiteräinen, terävä miekka, ja hänen kasvonsa olivat kuin aurinko, kun se paistaa voimassaan.',
        17: 'Kun näin hänet, kaaduin kuin kuolleena hänen jalkojensa juureen. Mutta hän pani oikean kätensä päälleni sanoen: "Älä pelkää! Minä olen ensimmäinen ja viimeinen,',
        18: 'ja elän, ja olin kuollut, ja katso, elän iäisyyksien iäisyyksiin, ja minulla on helvetin ja kuoleman avaimet.',
        19: 'Kirjoita, mitä olet nähnyt, mitä nyt on ja mitä tämän jälkeen tapahtuu.',
        20: 'Seitsemän tähden salaisuus, jotka näit oikeassa kädessäni, ja seitsemän kultaisen lampunjalan salaisuus on tämä: ne seitsemän tähteä ovat seitsemän seurakunnan enkelit, ja ne seitsemän lampunjalkaa ovat seitsemän seurakuntaa."',
    },
    2: {
        1: '"Efeson seurakunnan enkelille kirjoita: \'Näin sanoo se, joka pitää seitsemää tähteä oikeassa kädessään, se, joka kulkee seitsemän kultaisen lampunjalan keskellä:',
        2: 'Tiedän tekosi, vaivannäkösi ja kärsivällisyytesi, ja ettet voi sietää pahoja. Sinä olet koetellut niitä, jotka väittävät olevansa apostoleja eivätkä ole, ja olet havainnut heidät valehtelijoiksi.',
        3: 'Olet kestänyt ja sinulla on kärsivällisyyttä, ja olet tehnyt työtä nimeni tähden, etkä ole uupunut.',
        4: 'Mutta se minulla on sinua vastaan, että olet hylännyt ensimmäisen rakkautesi.',
        5: 'Muista siis, mistä olet langennut, ja tee parannus, ja tee ensimmäisiä tekoja. Mutta jos et, tulen pian luoksesi ja työnnän lampunjalkasi paikaltaan, ellet tee parannusta.',
        6: 'Mutta se sinulla on, että vihaat nikolaiittojen tekoja, joita minäkin vihaan.',
        7: "Jolla on korva, kuulkoon, mitä Henki seurakunnille sanoo. Sen, joka voittaa, annan syödä elämän puusta, joka on Jumalan paratiisissa.'",
        8: "Smyrnan seurakunnan enkelille kirjoita: 'Näin sanoo ensimmäinen ja viimeinen, joka kuoli ja virkosi eloon:",
        9: 'Minä tiedän tekosi, ahdistuksesi ja köyhyytesi – sinä olet kuitenkin rikas – ja tiedän kärsimäsi pilkan niiltä, jotka sanovat olevansa juutalaisia, eivätkä ole, vaan ovat saatanan synagoga.',
        10: 'Älä pelkää sitä, mitä tulet kärsimään. Katso, perkele heittää muutamia teistä vankilaan, että teidät pantaisiin koetukselle, ja teillä tulee olemaan ahdistusta kymmenen päivää. Ole uskollinen kuolemaan asti, niin annan sinulle elämän kruunun.',
        11: "Jolla on korva, kuulkoon, mitä Henki sanoo seurakunnille. Sitä, joka voittaa, toinen kuolema ei vahingoita.'",
        12: "Pergamon seurakunnan enkelille kirjoita: 'Näin sanoo se, jolla on kaksiteräinen, terävä miekka:",
        13: 'Tiedän tekosi ja sen, missä asut, nimittäin siellä, missä on saatanan valtaistuin, ja pidät nimestäni kiinni etkä ole kieltänyt uskoa minuun niinäkään päivinä, jolloin Antipas, uskollinen todistajani, tapettiin luonanne, siellä, missä saatana asuu.',
        14: 'Mutta minulla on jotakin sinua vastaan: sinulla on siellä niitä, jotka pitävät kiinni Bileamin opista, sen, joka opetti Baalakille Israelin lasten edessä viettelystä syödä epäjumalille uhrattua ja harjoittaa haureutta.',
        15: 'Niin myös sinulla on niitä, jotka pitävät kiinni nikolaiittojen opista, jota vihaan.',
        16: 'Muuta siis mielesi. Mutta jos et, niin tulen luoksesi pian ja sodin heitä vastaan suuni miekalla.',
        17: "Jolla on korva, kuulkoon, mitä Henki seurakunnille sanoo. Sille, joka voittaa, annan salattua mannaa ja annan hänelle valkoisen kiven ja kiveen kirjoitetun uuden nimen, jota ei tiedä kukaan muu kuin sen saaja.'",
        18: "Tyatiran seurakunnan enkelille kirjoita: 'Näin sanoo Jumalan Poika, jonka silmät ovat kuin tulen liekki ja jonka jalat ovat kuin kiiltävä vaski:",
        19: 'Tiedän tekosi, rakkautesi, palveluksesi, uskosi, kärsivällisyytesi ja että viimeiset tekosi ovat useammat kuin ensimmäiset.',
        20: 'Mutta minulla on sinua vastaan jotakin, se, että sallit tuon naisen, Iisebelin, joka sanoo itseään profeetaksi, opettaa ja eksyttää palvelijoitani harjoittamaan haureutta ja syömään epäjumalille uhrattua.',
        21: 'Olen antanut hänelle aikaa mielenmuutokseen, mutta hän ei ole tehnyt parannusta haureudestaan.',
        22: 'Katso, minä syöksen hänet tautivuoteeseen, ja suureen ahdistukseen ne, jotka hänen kanssaan tekevät huorin, jos eivät muuta mieltään eivätkä luovu hänen teoistaan.',
        23: 'Hänen lapsensa surmaan kuolemalla, ja kaikki seurakunnat saavat tuntea, että minä olen se, joka tutkin munuaiset ja sydämet, ja annan teille kullekin tekojenne mukaan.',
        24: 'Mutta teille muille Tyatirassa oleville, kaikille, joilla ei ole tätä oppia, teille, jotka ette ole tulleet tuntemaan, niin kuin he sanovat, saatanan syvyyksiä, sanon: en pane päällenne muuta kuormaa.',
        25: 'Pitäkää vain se, mitä teillä on, siihen asti kunnes tulen.',
        26: 'Sille, joka voittaa ja ottaa loppuun asti vaarin teoistani, annan vallan hallita pakanoita,',
        27: 'ja hän on kaitseva heitä rautaisella valtikalla, kuin saviastiat heidät särjetään – kuten minäkin sain siihen Isältäni vallan –',
        28: 'ja annan hänelle aamutähden.',
        29: 'Jolla on korva, kuulkoon, mitä Henki seurakunnille sanoo.\'"',
    },
    3: {
        1: '"Sardeen seurakunnan enkelille kirjoita: \'Näin sanoo se, jolla on Jumalan seitsemän henkeä ja seitsemän tähteä: Tiedän tekosi: sinulla on se nimi, että elät, mutta olet kuollut.',
        2: 'Herää valvomaan ja vahvista jäljellejääneitä, niitä, jotka ovat olleet kuolemaisillaan, sillä en ole havainnut tekojasi täydellisiksi Jumalani edessä.',
        3: 'Muista siis, kuinka olet saanut ja kuullut, ja säilytä se ja muuta mielesi. Jos et valvo, tulen päällesi kuin varas, etkä tiedä, millä hetkellä tulen päällesi.',
        4: 'Sinulla on Sardeessakin muutamia harvoja nimiä, jotka eivät ole tahrineet vaatteitaan, ja he tulevat vaeltamaan kanssani valkoisissa vaatteissa, sillä he ovat siihen arvollisia.',
        5: 'Joka voittaa, puetaan valkoisiin vaatteisiin, enkä pyyhi pois hänen nimeään elämän kirjasta, ja olen tunnustava hänen nimensä Isäni edessä ja hänen enkeliensä edessä.',
        6: "Jolla on korva, kuulkoon, mitä Henki seurakunnille sanoo.'",
        7: "Filadelfian seurakunnan enkelille kirjoita: 'Näin sanoo Pyhä ja Tosi, jolla on Daavidin avain, se, joka avaa, eikä kukaan sulje, ja joka sulkee, eikä kukaan avaa:",
        8: 'Tiedän tekosi. Katso, olen pannut eteesi avoimen oven, eikä kukaan voi sitä sulkea, sillä voimasi on vähäinen, ja olet pitänyt sanani etkä ole kieltänyt nimeäni.',
        9: 'Katso, annan sinulle saatanan synagogasta niitä, jotka sanovat olevansa juutalaisia, eivätkä ole, vaan valehtelevat. Katso, olen pannut heidät tulemaan ja kumartumaan jalkojesi eteen ja tietämään, että minä olen sinua rakastanut.',
        10: 'Koska olet pitänyt kärsivällisyyteni sanan, minäkin otan vaarin sinusta ja varjelen sinut koetuksen hetkestä, joka on tuleva yli koko maanpiirin koettelemaan niitä, jotka asuvat maan päällä.',
        11: 'Katso, tulen pian. Pidä kiinni siitä, mitä sinulla on, ettei kukaan ottaisi kruunuasi.',
        12: 'Sen, joka voittaa, teen pylvääksi Jumalani temppeliin, eikä hän koskaan enää lähde sieltä ulos, ja kirjoitan häneen Jumalani nimen ja Jumalani kaupungin nimen, sen uuden Jerusalemin, joka laskeutuu alas taivaasta Jumalani luota, ja uuden nimeni.',
        13: "Jolla on korva, kuulkoon, mitä Henki seurakunnille sanoo.'",
        14: "Laodikean seurakunnan enkelille kirjoita: 'Näin sanoo Aamen, uskollinen ja tosi todistaja, Jumalan luomakunnan alku:",
        15: 'Tiedän tekosi: et ole kylmä etkä kuuma. Oi, jospa olisit kylmä tai kuuma!',
        16: 'Näin ollen, koska olet haalea, etkä kylmä etkä kuuma, oksennan sinut suustani ulos.',
        17: 'Sillä sanot: Olen rikas, olen rikastunut enkä tarvitse mitään, etkä tiedä, että sinä olet kurja, säälittävä, köyhä, sokea ja alaston.',
        18: 'Neuvon sinua ostamaan minulta kultaa, tulessa puhdistettua, että rikastuisit, ja valkoiset vaatteet, jotta pukeutuisit niihin eikä alastomuutesi häpeä näkyisi, ja silmävoidetta voidellaksesi silmäsi, jotta näkisit.',
        19: 'Kaikkia niitä, joita rakastan, nuhtelen ja kuritan. Ahkeroi siis ja muuta mielesi.',
        20: 'Katso, seison ovella ja kolkutan. Jos joku kuulee ääneni ja avaa oven, käyn sisälle hänen luokseen ja aterioin hänen kanssaan, ja hän minun kanssani.',
        21: 'Sen, joka voittaa, annan istua kanssani valtaistuimellani, niin kuin minäkin olen voittanut ja istunut Isäni kanssa hänen valtaistuimellaan.',
        22: 'Jolla on korva, kuulkoon, mitä Henki sanoo seurakunnille.\'"',
    },
    4: {
        1: 'Sen jälkeen näin, ja katso: taivaassa oli ovi avattuna, ja ensimmäinen ääni, jonka olin kuullut puhuvan minulle kuin torven, sanoi: "Nouse ylös tänne, niin näytän sinulle, mitä tämän jälkeen pitää tapahtua."',
        2: 'Heti olin Hengessä. Katso, taivaassa oli valtaistuin, ja valtaistuimella oli istuja.',
        3: 'Istuja oli näöltään jaspis- ja sardionkiven kaltainen, ja valtaistuimen ympärillä oli sateenkaari, näöltään smaragdin kaltainen.',
        4: 'Valtaistuimen ympärillä oli kaksikymmentä neljä valtaistuinta, ja valtaistuimilla istui kaksikymmentä neljä vanhinta, puettuina valkoisiin vaatteisiin, ja heillä oli päässään kultakruunut.',
        5: 'Valtaistuimesta lähti salamoita, ukkosen jyrinää ja ääniä, ja valtaistuimen edessä paloi seitsemän tulisoihtua, jotka ovat Jumalan seitsemän henkeä.',
        6: 'Valtaistuimen edessä oli lasimeri, kristallin näköinen. Valtaistuimen keskellä ja valtaistuimen ympärillä oli neljä olentoa, täynnä silmiä edestä ja takaa.',
        7: 'Ensimmäinen olento oli leijonan näköinen, toinen olento nuoren härän näköinen, kolmannella olennolla oli kuin ihmisen kasvot, ja neljäs olento oli lentävän kotkan näköinen.',
        8: 'Niillä neljällä olennolla oli kullakin kuusi siipeä, ja ne olivat ympäriinsä ja sisältä silmiä täynnä. Ne sanoivat lakkaamatta yötä päivää: "Pyhä, pyhä, pyhä on Herra Jumala, Kaikkivaltias, joka oli ja joka on ja joka tuleva on."',
        9: 'Kun olennot antavat ylistyksen, kunnian ja kiitoksen hänelle, joka valtaistuimella istuu, joka elää iäisyyksien iäisyyksiin,',
        10: 'kaksikymmentä neljä vanhinta lankeaa hänen eteensä, joka valtaistuimella istuu, ja kumartaen rukoilee häntä, joka elää iäisyyksien iäisyyksiin, ja heittää kruununsa valtaistuimen eteen sanoen:',
        11: '"Sinä, Herra, olet arvollinen saamaan ylistyksen ja kunnian ja voiman, sillä sinä olet luonut kaiken, ja sinun tahdostasi ne ovat olemassa ja ovat luodut."',
    },
    5: {
        1: 'Sitten näin valtaistuimella istuvan oikeassa kädessä kirjakäärön, sisältä ja päältä täyteen kirjoitetun, seitsemällä sinetillä suljetun.',
        2: 'Näin väkivahvan enkelin suurella äänellä kuuluttavan: "Kuka on arvollinen avaamaan tämän kirjan ja päästämään sen sinetit?"',
        3: 'Eikä kukaan taivaassa, ei maan päällä eikä maan alla voinut avata kirjaa eikä katsoa siihen.',
        4: 'Minä itkin kovasti, ettei ketään havaittu arvolliseksi avaamaan kirjaa eikä katsomaan siihen.',
        5: 'Mutta yksi vanhimmista sanoi minulle: "Älä itke! Katso, leijona Juudan sukukunnasta, Daavidin juurivesa, on voittanut avatakseen kirjan ja irrottaakseen sen seitsemän sinettiä."',
        6: 'Ja näin, että valtaistuimen ja niiden neljän olennon ja vanhinten keskellä seisoi Karitsa, ikään kuin teurastettu. Hänellä oli seitsemän sarvea ja seitsemän silmää, jotka ovat seitsemän Jumalan henkeä, lähetetyt kaikkeen maailmaan.',
        7: 'Hän tuli ja otti kirjan valtaistuimella istuvan oikeasta kädestä.',
        8: 'Kun hän oli ottanut kirjan, neljä olentoa ja kaksikymmentä neljä vanhinta lankesivat Karitsan eteen. Heillä oli kullakin sitra, ja heillä oli kultamaljat täynnä suitsutuksia, jotka ovat pyhien rukoukset.',
        9: 'He veisasivat uutta virttä, sanoen: "Sinä olet arvollinen ottamaan kirjan ja avaamaan sen sinetit, sillä sinut on teurastettu ja olet verelläsi ostanut Jumalalle ihmiset kaikista sukukunnista, kielistä, [Israelin] kansasta ja pakanoista',
        10: 'ja tehnyt meidät Jumalallemme kuninkaiksi ja papeiksi, ja tulemme hallitsemaan maan päällä."',
        11: '[Minä] näin ja kuulin monien enkelien äänen valtaistuimen, olentojen ja vanhinten ympäriltä, ja heidän lukunsa oli kymmenentuhatta kertaa kymmenentuhatta ja tuhat kertaa tuhat,',
        12: 'sanovan suurella äänellä: "Karitsa, joka on teurastettu, on arvollinen saamaan voiman, rikkauden, viisauden, väkevyyden, kunnian, kirkkauden ja ylistyksen."',
        13: 'Kaikkien luotujen, jotka ovat taivaassa ja maan päällä ja maan alla ja merellä, ja kaikkien niissä olevien kuulin sanovan: "Hänelle, joka valtaistuimella istuu, ja Karitsalle ylistys, kunnia, kirkkaus ja valta iäisyyksien iäisyyksiin!"',
        14: 'Ja neljä olentoa sanoi: "Aamen", ja vanhimmat lankesivat kasvoilleen ja kumartaen rukoilivat sitä, joka elää iäisyyksien iäisyyksiin.',
    },
    6: {
        1: 'Sitten näin, kuinka Karitsa avasi yhden sineteistä, ja kuulin yhden neljästä olennosta sanovan kuin ukkosen äänellä: "Tule ja katso!"',
        2: 'Näin, ja katso: valkoinen hevonen, ja sen selässä istuvalla oli jousi, ja hänelle annettiin seppele, ja hän lähti voittajana ja voittamaan.',
        3: 'Kun Karitsa avasi toisen sinetin, kuulin toisen olennon sanovan: "Tule ja katso!"',
        4: 'Niin lähti toinen hevonen, tulipunainen, ja sen selässä istuvalle annettiin valta ottaa pois rauha maasta, että ihmiset surmaisivat toisiaan, ja hänelle annettiin suuri miekka.',
        5: 'Kun Karitsa avasi kolmannen sinetin, kuulin kolmannen olennon sanovan: "Tule ja katso!" Ja näin, ja katso: musta hevonen, ja sen selässä istuvalla oli kädessään vaaka.',
        6: 'Kuulin ikään kuin äänen neljän olennon keskeltä sanovan: "Koiniks-mitta vehnää yhden denaarin, ja kolme koiniksia ohria yhden denaarin! Mutta älä turmele öljyä äläkä viiniä."',
        7: 'Kun Karitsa avasi neljännen sinetin, kuulin neljännen olennon äänen sanovan: "Tule ja katso!"',
        8: 'Näin, ja katso: harmahtava hevonen! Sen selässä istuvan nimi oli Kuolema, ja Kadotus seurasi hänen mukanaan, ja heidän valtaansa annettiin neljäs osa maasta, annettiin valta tappaa miekalla, nälällä, rutolla ja maan pedoilla.',
        9: 'Kun Karitsa avasi viidennen sinetin, näin alttarin alla niiden sielut, jotka olivat surmatut Jumalan sanan tähden ja sen todistuksen tähden, joka heillä oli.',
        10: 'He huusivat suurella äänellä sanoen: "Kuinka kauaksi aikaa sinä, pyhä ja tosi Valtias, jätät tuomitsematta ja kostamatta veremme niille, jotka maan päällä asuvat?"',
        11: 'Heille annettiin kullekin pitkä valkoinen viitta, ja heille sanottiin, että pysyisivät levollisina vielä vähän aikaa, kunnes täyttyy myös heidän palvelustovereidensa ja veljiensä luku, jotka tullaan tappamaan niin kuin heidätkin [tapettiin].',
        12: 'Näin, kuinka Karitsa avasi kuudennen sinetin. Tuli suuri maanjäristys, ja aurinko meni mustaksi kuin karvainen säkkipuku, ja kuu tuli kuin vereksi,',
        13: 'ja taivaan tähdet putosivat maahan, niin kuin viikunapuu varistaa raakileensa, kun suuri tuuli sitä ravistelee,',
        14: 'ja taivas väistyi pois kuin kirjakäärö, joka kääritään kokoon, ja kaikki vuoret ja saaret siirtyivät sijoiltaan.',
        15: 'Maan kuninkaat, ylimykset, rikkaat, sotapäälliköt, mahtimiehet, ja kaikki orjat ja vapaat kätkeytyivät luoliin ja vuorten rotkoihin',
        16: 'ja sanoivat vuorille ja kallioille: "Langetkaa päällemme ja kätkekää meidät hänen kasvoiltaan, joka valtaistuimella istuu, ja Karitsan vihalta!',
        17: 'Sillä hänen vihansa suuri päivä on tullut, ja kuka voi kestää?"',
    },
    7: {
        1: 'Sen jälkeen näin neljän enkelin seisovan maan neljällä kulmalla ja pitelevän kiinni maan neljää tuulta, ettei tuuli puhaltaisi maan päälle, meren päälle eikä yhteenkään puuhun.',
        2: 'Näin erään muun enkelin kohoavan auringonnoususta, ja hänellä oli elävän Jumalan sinetti, ja hän huusi suurella äänellä niille neljälle enkelille, joille oli annettu maan ja meren vahingoittaminen,',
        3: 'ja sanoi: "Älkää vahingoittako maata älkääkä merta, älkää myöskään puita, ennen kuin olemme painaneet sinetin Jumalamme palvelijoiden otsaan."',
        4: 'Kuulin sinetillä merkittyjen luvun, sata neljäkymmentä neljä tuhatta merkittyä kaikista israelilaisten sukukunnista:',
        5: 'Juudan sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Ruubenin sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Gaadin sukukunnasta kaksitoista tuhatta sinetillä merkittyä,',
        6: 'Asserin sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Naftalin sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Manassen sukukunnasta kaksitoista tuhatta sinetillä merkittyä,',
        7: 'Simeonin sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Leevin sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Isaskarin sukukunnasta kaksitoista tuhatta sinetillä merkittyä,',
        8: 'Sebulonin sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Joosefin sukukunnasta kaksitoista tuhatta sinetillä merkittyä ja Benjaminin sukukunnasta kaksitoista tuhatta sinetillä merkittyä.',
        9: 'Tämän jälkeen näin, ja katso, oli suuri joukko, jota kukaan ei voinut laskea, kaikista kansanheimoista, sukukunnista, kansakunnista ja kielistä, ja he seisoivat valtaistuimen edessä ja Karitsan edessä puettuina pitkiin valkoisiin vaatteisiin palmut käsissään,',
        10: 'ja he huusivat suurella äänellä sanoen: "Autuus on Jumalallamme, joka valtaistuimella istuu, ja Karitsalla."',
        11: 'Kaikki enkelit seisoivat piirissä valtaistuimen, vanhinten ja neljän olennon ympärillä ja lankesivat kasvoilleen valtaistuimen eteen ja kumartaen rukoilivat Jumalaa,',
        12: 'sanoen: "Aamen! Ylistys, kirkkaus, viisaus, kiitos, kunnia, voima ja väkevyys meidän Jumalallemme iäisyyksien iäisyyksiin, aamen!"',
        13: 'Niin yksi vanhimmista puhui minulle ja sanoi: "Keitä ovat nämä pitkiin valkoisiin vaatteisiin puetut, ja mistä he ovat tulleet?"',
        14: 'Sanoin hänelle: "Herrani, sinä sen tiedät." Ja hän sanoi minulle: "Nämä ovat ne, jotka tulevat suuresta ahdistuksesta, ja he ovat pesseet vaatteensa ja valkaisseet ne Karitsan veressä.',
        15: 'Sen tähden he ovat Jumalan valtaistuimen edessä ja palvelevat häntä yötä päivää hänen temppelissään, ja hän, joka valtaistuimella istuu, on levittävä telttamajansa heidän ylitseen.',
        16: 'Heidän ei tule enää nälkä eikä enää jano, eikä aurinko satu heihin, eikä mikään helle,',
        17: 'sillä Karitsa, joka on valtaistuimen keskellä, on kaitseva heitä ja johdattava heidät elämän vetten lähteille, ja Jumala on pyyhkivä pois kaikki kyyneleet heidän silmistään."',
    },
    8: {
        1: 'Kun hän avasi seitsemännen sinetin, taivaaseen tuli äänettömyys noin puoleksi tunniksi.',
        2: 'Ja näin ne seitsemän enkeliä, jotka seisoivat Jumalan edessä, ja heille annettiin seitsemän torvea.',
        3: 'Tuli eräs muu enkeli ja asettui alttarin ääreen pitäen kultaista suitsutusastiaa, ja hänelle annettiin paljon suitsukkeita pantavaksi kaikkien pyhien rukouksiin kultaiselle alttarille, joka oli valtaistuimen edessä.',
        4: 'Suitsukkeiden savu nousi pyhien rukousten kanssa enkelin kädestä Jumalan eteen.',
        5: 'Sitten enkeli otti suitsutusastian ja täytti sen alttarin tulella ja heitti maan päälle. Silloin syntyi ukkosenjyrinää, ääniä, salamoita ja maanjäristystä.',
        6: 'Seitsemän enkeliä, joilla oli seitsemän torvea, valmistautui puhaltamaan torviin.',
        7: 'Ensimmäinen enkeli puhalsi torveen. Tuli rakeita ja tulta, verellä sekoitettuja, ja ne heitettiin maan päälle. Ja kolmas osa maata paloi, ja kolmas osa puita paloi, ja kaikki vihertävä ruoho paloi.',
        8: 'Toinen enkeli puhalsi torveen. Mereen heitettiin kuin suuri, tulena palava vuori, ja kolmas osa merta muuttui vereksi,',
        9: 'ja kolmas osa luoduista, mitä meressä on ja joissa on henki, kuoli, ja kolmas osa laivoista hukkui.',
        10: 'Kolmas enkeli puhalsi torveen. Niin taivaasta putosi suuri tähti, palava kuin tulisoihtu, ja se putosi kolmanteen osaan virtoja ja vesilähteisiin.',
        11: 'Tähden nimi oli Koiruoho. Kolmas osa vesistä muuttui koiruohoksi, ja paljon ihmisiä kuoli vedestä, koska se oli tullut karvaaksi.',
        12: 'Neljäs enkeli puhalsi torveen. Silloin kolmas osa auringosta, kolmas osa kuusta ja kolmas osa tähdistä lyötiin vitsauksella, niin että kolmas osa niistä pimeni ja päivä kolmannelta osaltaan oli valoton ja samoin myös yö.',
        13: 'Sitten näin ja kuulin erään enkelin keskitaivaalla sanovan suurella äänellä: "Voi, voi, voi maan päällä asuvia niiden jäljellä olevien torvien äänten tähden, joihin kolme enkeliä vielä puhaltaa!"',
    },
    9: {
        1: 'Viides enkeli puhalsi torveen, ja näin taivaasta maahan pudonneen tähden, ja sille annettiin syvyyden kaivon avain.',
        2: 'Se avasi syvyyden kaivon, ja kaivosta nousi savua, kuin savua suuresta pätsistä, ja kaivon savu pimitti auringon ja ilman.',
        3: 'Savusta lähti heinäsirkkoja maan päälle, ja niille annettiin valta, niin kuin maan skorpioneilla on valta,',
        4: 'ja niille sanottiin, etteivät ne saa vahingoittaa maan ruohoa, mitään vihantaa eivätkä yhtään puuta, vaan ainoastaan niitä ihmisiä, joilla ei ole otsassaan Jumalan sinettiä.',
        5: 'Niiden annettiin vaivata heitä viisi kuukautta, mutta ei tappaa heitä, ja ne vaivasivat, niin kuin vaivaa skorpioni, kun se pistää ihmistä.',
        6: 'Niinä päivinä ihmiset etsivät kuolemaa, eivätkä sitä löydä. He haluavat kuolla, mutta kuolema pakenee heitä.',
        7: 'Heinäsirkat olivat sotaan valmistautuneiden hevosten kaltaisia, ja niillä oli päässään kuin seppeleet, kullan näköiset, ja niiden kasvot olivat kuin ihmisten kasvot.',
        8: 'Niiden hiukset olivat kuin naisten hiukset, ja niiden hampaat olivat kuin leijonien hampaat.',
        9: 'Niillä oli haarniskat ikään kuin rautahaarniskat, ja niiden siipien kohina oli kuin sotavaunujen ryske monien hevosten juostessa taisteluun.',
        10: 'Niillä oli pyrstöt kuin skorpioneilla, ja pyrstöissään niillä oli pistimet. Niillä oli valta vahingoittaa ihmisiä viisi kuukautta.',
        11: 'Niillä oli kuninkaanaan syvyyden enkeli, jonka nimi hepreaksi on Abaddon ja kreikaksi nimi on Apollyon.',
        12: 'Ensimmäinen "voi!" on mennyt. Katso, tulee vielä kaksi voi-huutoa tämän jälkeen.',
        13: 'Kuudes enkeli puhalsi torveen. Kuulin yhden äänen tulevan kultaisen alttarin neljästä sarvesta, Jumalan edestä,',
        14: 'ja ääni sanoi kuudennelle enkelille, jolla oli torvi: "Päästä ne neljä enkeliä, jotka ovat sidottuina suurella Eufrat-virralla."',
        15: 'Silloin päästettiin neljä enkeliä, jotka hetkelleen, päivälleen, kuukaudelleen ja vuodelleen olivat valmiina tappamaan kolmannen osan ihmisistä.',
        16: 'Ratsuväen joukkojen luku oli kaksikymmentä tuhatta kertaa kymmenen tuhatta. Kuulin niiden luvun.',
        17: 'Tällaisilta näyttivät minusta hevoset ja niiden selässä istujat näyssä: ratsastajilla oli tulipunaiset, hyasintin väriset ja rikinkeltaiset haarniskat, ja hevosten päät olivat kuin leijonien päät, ja niiden suusta lähti tulta, savua ja rikkiä.',
        18: 'Näistä kolmesta sai kolmas osa ihmisiä surmansa: tulesta, savusta ja rikistä, jotka lähtivät niiden suusta.',
        19: 'Sillä niiden voima on niiden suussa ja niiden hännässä. Niiden hännät näet ovat käärmeitten kaltaisia, ja niissä on päät, joilla ne vahingoittavat.',
        20: 'Jäljelle jääneet ihmiset, ne, joita ei tapettu näillä vitsauksilla, eivät tehneet parannusta kättensä teoista, niin että olisivat lakanneet kumartamasta riivaajia sekä kultaisia, hopeaisia, vaskisia, kivisiä ja puisia epäjumalankuvia, jotka eivät voi nähdä, kuulla eivätkä kävellä.',
        21: 'He eivät tehneet parannusta murhistaan, taioistaan, haureudestaan eivätkä varkauksistaan.',
    },
    10: {
        1: 'Näin erään toisen, väkivahvan enkelin tulevan alas taivaasta. Hänellä oli pilvi verhona, ja sateenkaari oli hänen päänsä päällä. Hänen kasvonsa olivat kuin aurinko, ja hänen jalkansa kuin tuliset pilarit.',
        2: 'Hänellä oli kädessään avattu pieni kirjakäärö, ja hän laski oikean jalkansa meren päälle ja vasemman maan päälle',
        3: 'ja huusi suurella äänellä, niin kuin leijona karjahtelee. Kun hän huusi, antoi seitsemän ukkosenjyrinää ääntensä puhua.',
        4: 'Kun seitsemän ukkosenjyrinää oli puhunut, aioin kirjoittaa, mutta kuulin äänen taivaasta sanovan: "Sinetöi, mitä seitsemän ukkosenjyrinää puhui, äläkä sitä kirjoita."',
        5: 'Enkeli, jonka näin seisovan meren päällä ja maan päällä, kohotti kätensä taivasta kohti',
        6: 'ja vannoi hänen kauttaan, joka elää iäisyyksien iäisyyksiin, hänen, joka on luonut taivaan ja mitä siinä on, ja maan ja mitä siinä on, ja meren ja mitä siinä on, ettei enää ole oleva aikaa,',
        7: 'vaan että niinä päivinä, jolloin seitsemännen enkelin ääni kuuluu hänen puhaltaessaan torveen, Jumalan salaisuus käy täytäntöön sen hyvän sanoman mukaan, jonka hän on ilmoittanut palvelijoilleen profeetoille.',
        8: 'Sen äänen, jonka olin kuullut taivaasta, kuulin taas puhuvan minulle ja sanovan: "Mene ja ota avattu pieni kirjakäärö, joka on meren ja maan päällä seisovan enkelin kädessä."',
        9: 'Lähdin enkelin luo ja pyysin, että hän antaisi minulle pienen kirjakäärön. Hän sanoi minulle: "Ota ja syö se. Se karvastelee vatsassasi, mutta suussasi se on makea kuin hunaja."',
        10: 'Otin kirjakäärön enkelin kädestä ja söin sen. Se oli suussani makea kuin hunaja, mutta sen syötyäni vatsaani karvasteli.',
        11: 'Minulle sanottiin: "Sinun tulee taas profetoida monista kansakunnista, pakanakansoista, kielistä ja kuninkaista."',
    },
    11: {
        1: 'Minulle annettiin sauvan kaltainen ruoko. Enkeli oli noussut seisomaan ja sanoi: "Nouse ja mittaa Jumalan temppeli ja alttari ja ne, jotka siinä kumartaen rukoilevat.',
        2: 'Mutta temppelin ulkopuolella oleva esikartano jätä ulkopuolelle äläkä sitä mittaa, sillä se on annettu pakanoille. He tallaavat pyhää kaupunkia neljäkymmentäkaksi kuukautta.',
        3: 'Annan kahdelle todistajalleni toimeksi säkkipukuihin puettuina profetoida tuhannen kahdensadan kuudenkymmenen päivän ajan."',
        4: 'Nämä ovat ne kaksi öljypuuta ja ne kaksi lampunjalkaa, jotka seisovat maan Herran edessä.',
        5: 'Jos joku tahtoo heitä vahingoittaa, lähtee tuli heidän suustaan ja nielee heidän vihollisensa. Jos joku tahtoo heitä vahingoittaa, hänen täytyy saada surmansa sillä tavalla.',
        6: 'Heillä on valta sulkea taivas, niin ettei sadetta tule heidän profetoimisensa päivinä, ja heillä on valta muuttaa vedet vereksi ja lyödä maata kaikilla vitsauksilla, niin usein kuin tahtovat.',
        7: 'Kun he ovat lopettaneet todistamisensa, peto, joka nousee syvyydestä, ryhtyy sotaan heitä vastaan, voittaa heidät ja tappaa heidät.',
        8: 'Heidän ruumiinsa viruvat sen suuren kaupungin kadulla, jota hengellisesti kutsutaan Sodomaksi ja Egyptiksi ja jossa ristiinnaulittiin myös heidän Herransa.',
        9: 'Ihmiset eri kansoista, sukukunnista, kielistä ja pakanakansoista näkevät heidän ruumiinsa kolme ja puoli päivää, eivätkä salli, että heidän ruumiinsa pannaan hautaan.',
        10: 'Ne, jotka maan päällä asuvat, iloitsevat heistä ja riemuitsevat. He lähettävät lahjoja toisilleen. Sillä nämä kaksi profeettaa olivat vaivanneet niitä, jotka maan päällä asuvat.',
        11: 'Niiden kolmen ja puolen päivän kuluttua tuli Jumalasta elämän henki heidän päälleen, ja he nousivat jaloilleen, ja suuri pelko valtasi ne, jotka näkivät heidät.',
        12: 'He kuulivat suuren äänen taivaasta sanovan heille: "Nouskaa tänne!" Niin he nousivat taivaaseen pilvessä, ja heidän vihollisensa näkivät heidät.',
        13: 'Sillä hetkellä tapahtui suuri maanjäristys, ja kymmenes osa kaupunkia luhistui, ja maanjäristyksessä sai surmansa seitsemäntuhatta nimeä, ja muut pelästyivät ja antoivat kunnian taivaan Jumalalle.',
        14: 'Toinen "voi!" on mennyt. Katso, kolmas "voi!" tulee pian.',
        15: 'Seitsemäs enkeli puhalsi torveen. Silloin kuului taivaassa suuria ääniä, jotka sanoivat: "Maailman kuninkuus on tullut Herrallemme ja hänen Voidellulleen, ja hän on hallitseva iäisyyksien iäisyyksiin."',
        16: 'Kaksikymmentä neljä vanhinta, jotka istuivat valtaistuimillaan Jumalan edessä, lankesi kasvoilleen ja rukoili kumartaen Jumalaa,',
        17: 'sanoen: "Kiitämme sinua, Herra Jumala, Kaikkivaltias, joka olet ja joka olit, siitä, että olet ottanut suuren voimasi ja hallitset.',
        18: 'Pakanat olivat pitäneet vihaa, mutta nyt sinun vihasi on tullut, ja on tullut aika tuomita kuolleet ja maksaa palkka palvelijoillesi profeetoille, pyhille ja niille, jotka sinun nimeäsi pelkäävät, pienille ja suurille, ja saattaa turmioon maan turmelijat."',
        19: 'Jumalan temppeli taivaassa aukeni, ja hänen liittonsa arkki näkyi hänen temppelissään, ja tuli salamoita, ääniä, ukkosen jyrinää, maanjäristystä ja suuria rakeita.',
    },
    12: {
        1: 'Näkyi suuri merkki taivaassa: vaimo, vaatetettu auringolla, ja kuu hänen jalkojensa alla, ja hänen päässään seppeleenä kaksitoista tähteä.',
        2: 'Hän oli raskaana ja huusi synnytyskivuissaan, kun hänen oli tuskallista synnyttää.',
        3: 'Näkyi myös toinen merkki taivaassa: katso: suuri, tulipunainen lohikäärme, jolla oli seitsemän päätä ja kymmenen sarvea, ja sen päissä seitsemän kruunua.',
        4: 'Sen pyrstö pyyhkäisi pois kolmannen osan taivaan tähtiä ja heitti ne maan päälle. Lohikäärme seisoi synnyttämäisillään olevan vaimon edessä nielläkseen hänen lapsensa, kun hän sen synnyttäisi.',
        5: 'Ja vaimo synnytti pojan, joka on kaitseva kaikkia pakanakansoja rautaisella valtikalla, ja hänen lapsensa temmattiin Jumalan luo ja hänen valtaistuimensa luo.',
        6: 'Vaimo pakeni erämaahan, jossa hänellä oli Jumalan valmistama paikka, että häntä elätettäisiin siellä tuhat kaksisataa kuusikymmentä päivää.',
        7: 'Oli sota taivaassa: Miikael ja hänen enkelinsä sotivat lohikäärmettä vastaan, ja lohikäärme ja hänen enkelinsä sotivat,',
        8: 'mutta ne eivät voittaneet, eikä niillä enää ollut sijaa taivaassa.',
        9: 'Suuri lohikäärme, se vanha käärme, jota perkeleeksi ja saatanaksi kutsutaan, koko maanpiirin villitsijä, heitettiin maan päälle, ja hänen enkelinsä heitettiin hänen kanssaan.',
        10: 'Kuulin suuren äänen taivaassa sanovan: "Nyt on tullut pelastus, voima ja meidän Jumalamme valtakunta ja hänen Voideltunsa valta, sillä meidän veljiemme syyttäjä, joka yötä päivää syytti heitä Jumalamme edessä, on heitetty ulos.',
        11: 'He ovat voittaneet hänet Karitsan veren kautta ja todistuksensa sanan kautta, ja olleet rakastamatta henkeään kuolemaan asti.',
        12: 'Sen tähden riemuitkaa, taivaat, ja te, jotka niissä asutte! Voi maata ja merta, sillä perkele on astunut alas luoksenne pitäen suurta vihaa, koska tietää, että hänellä on vähän aikaa!"',
        13: 'Ja kun lohikäärme näki olevansa heitetty maan päälle, se ajoi takaa vaimoa, joka oli synnyttänyt miehen.',
        14: 'Mutta vaimolle annettiin suuren kotkan kaksi siipeä hänen lentääkseen erämaahan sille paikalleen, jossa häntä elätetään aika ja kaksi aikaa ja puoli aikaa poissa käärmeen näkyvistä.',
        15: 'Käärme syöksi kidastaan vaimon jälkeen vettä niin kuin virran saattaakseen hänet virran vietäväksi.',
        16: 'Mutta maa auttoi vaimoa: maa avasi suunsa ja nieli virran, jonka lohikäärme oli syössyt kidastaan.',
        17: 'Lohikäärme vihastui vaimoon, lähti käymään sotaa muita hänen jälkeläisiään vastaan, jotka pitävät Jumalan käskyt ja joilla on Jeesuksen todistus.',
    },
    13: {
        1: 'Seisoin meren hiekalla ja näin merestä nousevan pedon. Sillä oli seitsemän päätä ja kymmenen sarvea, ja sarvissaan kymmenen kruunua, ja päissään pilkkaava nimi.',
        2: 'Peto, jonka näin, oli leopardin näköinen. Sen jalat olivat kuin karhun, ja sen kita kuin leijonan kita. Lohikäärme antoi sille voimansa, valtaistuimensa ja suuren vallan.',
        3: 'Näin yhden sen päistä olevan kuin kuoliaaksi haavoitetun, mutta sen kuolinhaava parani, ja koko maa seurasi ihmetellen petoa.',
        4: 'He kumarsivat lohikäärmettä, koska se oli antanut sellaisen vallan pedolle, ja kumarsivat petoa sanoen: "Kuka on pedon kaltainen, ja kuka voi sotia sitä vastaan?"',
        5: 'Sille annettiin suu puhua suuria sanoja ja pilkkapuheita, ja sille annettiin valta tehdä sitä neljäkymmentä kaksi kuukautta.',
        6: 'Se avasi suunsa pilkkaamaan Jumalaa pilkatakseen hänen nimeään ja hänen majaansa, niitä, jotka taivaassa asuvat.',
        7: 'Sille annettiin valta käydä sotaa pyhiä vastaan ja voittaa heidät, ja sen valtaan annettiin jokainen sukukunta, kieli ja kansa.',
        8: 'Kaikki maan päällä asuvat tulevat kumartamaan sitä, jokainen, jonka nimeä ei ole kirjoitettu teurastetun Karitsan elämänkirjaan, aina maailman perustamisesta.',
        9: 'Jos kenellä on korva, kuulkoon.',
        10: 'Jos joku vie vankeuteen, hän joutuu itse vankeuteen. Jos joku tappaa miekalla, hänet pitää miekalla tappaa. Tässä on pyhien kärsivällisyys ja usko.',
        11: 'Näin toisen pedon nousevan maasta, ja sillä oli kaksi sarvea kuin karitsan sarvet, ja se puhui kuin lohikäärme.',
        12: 'Se käyttää kaikkea ensimmäisen pedon valtaa sen nähden ja saattaa maan ja siinä asuvat kumartamaan ensimmäistä petoa, sitä, jonka kuolinhaava parani.',
        13: 'Se tekee suuria ihmeitä, niin että saa tulenkin taivaasta lankeamaan maahan ihmisten edessä.',
        14: 'Se villitsee maan päällä asuvia niillä ihmeillä, joita sen annettiin tehdä pedon edessä. Se saa maan päällä asuvat tekemään sen pedon kuvan, jossa oli miekanhaava ja joka virkosi.',
        15: 'Sille annettiin valta antaa pedon kuvalle henki, että pedon kuva myös puhuisi ja saisi aikaan, että ketkä tahansa eivät kumartaneet pedon kuvaa, ne tapettaisiin.',
        16: 'Se saa kaikki, pienet ja suuret, sekä rikkaat että köyhät, sekä vapaat että orjat, panemaan merkin oikeaan käteensä tai otsaansa,',
        17: 'ettei kukaan muu voisi ostaa eikä myydä kuin se, jossa on merkki: pedon nimi tai sen nimen luku.',
        18: 'Tässä on viisaus. Jolla on ymmärrystä, laskekoon pedon luvun, sillä se on ihmisen luku. Sen luku on kuusisataa kuusikymmentä kuusi.',
    },
    14: {
        1: 'Sitten näin, ja katso, Karitsa seisoi Siionin vuorella, ja hänen kanssaan sata neljäkymmentä neljä tuhatta, joiden otsaan oli kirjoitettu hänen Isänsä nimi.',
        2: '[Minä] kuulin äänen taivaasta ikään kuin paljojen vetten kohinan ja ikään kuin suuren ukkosenjyrinän, ja ääni, jonka kuulin, oli kuin sitransoittajien, kun he soittavat sitrojaan.',
        3: 'He veisasivat uutta virttä valtaistuimen edessä ja neljän olennon ja vanhinten edessä, eikä kukaan voinut oppia sitä virttä, paitsi kaikki ne sata neljäkymmentä neljä tuhatta, jotka ovat ostetut maasta.',
        4: 'Nämä ovat ne, jotka eivät ole saastuttaneet itseään naisten kanssa, sillä he ovat neitsyitä. Nämä ovat ne, jotka seuraavat Karitsaa, mihin ikinä hän menee. Nämä ovat ostetut ihmisistä ensi hedelmänä Jumalalle ja Karitsalle,',
        5: 'eikä heidän suussaan ole havaittu petosta. He ovat tahrattomia Jumalan valtaistuimen edessä.',
        6: 'Näin keskitaivaalla lentävän erään toisen enkelin, jolla oli iankaikkinen evankeliumi julistettavana maan päällä asuville, jokaiselle kansalle, sukukunnalle, kielelle ja kansakunnalle.',
        7: 'Hän sanoi suurella äänellä: "Pelätkää Jumalaa ja antakaa hänelle kunnia, sillä hänen tuomionsa hetki on tullut. Kumartakaa häntä, joka on tehnyt taivaan, maan, meren ja vetten lähteet."',
        8: 'Seurasi vielä toinen enkeli, joka sanoi: "Kukistunut, kukistunut on suuri Babylon, joka haureutensa vihan viinillä on juottanut kaikkia kansoja."',
        9: 'Heitä seurasi kolmas enkeli, joka sanoi suurella äänellä: "Jos joku kumartaa petoa ja sen kuvaa ja ottaa sen merkin otsaansa tai käteensä,',
        10: 'niin hänkin on juova Jumalan vihan viiniä, joka sekoittamattomana on kaadettu hänen vihansa maljaan, ja häntä vaivataan tulella ja rikillä pyhien enkelien edessä ja Karitsan edessä.',
        11: 'Heidän vaivaamisensa savu on nouseva iäisyyksien iäisyyksiin, eikä niillä ole lepoa päivällä eikä yöllä, jotka kumartavat petoa ja sen kuvaa, eikä kenelläkään, joka ottaa sen nimen merkin.',
        12: 'Tässä on pyhien kärsivällisyys. Tässä ovat ne, jotka pitävät Jumalan käskyt ja uskon Jeesukseen."',
        13: 'Kuulin äänen taivaasta sanovan: "Kirjoita: Autuaat ovat ne kuolleet, jotka kuolevat Herrassa tästedes. Totisesti – sanoo Henki – he saavat levätä vaivannäöstään, sillä heidän tekonsa seuraavat heitä."',
        14: 'Näin, ja katso: valkoinen pilvi, ja pilvellä istui Ihmisen Pojan kaltainen päässään kultakruunu ja kädessään terävä sirppi.',
        15: 'Eräs toinen enkeli tuli temppelistä huutaen suurella äänellä pilvellä istuvalle: "Lähetä sirppisi ja leikkaa, sillä leikkuuaika on tullut, ja maan vilja on tuleentunut."',
        16: 'Pilvellä istuva heitti sirppinsä maan päälle, ja maa tuli leikatuksi.',
        17: 'Eräs toinen enkeli lähti taivaan temppelistä, ja hänelläkin oli terävä sirppi.',
        18: 'Alttarilta lähti vielä toinen enkeli, jolla oli tuli vallassaan, ja hän huusi suurella äänellä sille, jolla oli terävä sirppi, sanoen: "Lähetä terävä sirppisi ja korjaa tertut maan viiniköynnöksestä, sillä sen rypäleet ovat kypsyneet."',
        19: 'Enkeli heitti sirppinsä alas maahan ja korjasi maan viiniköynnöksen hedelmät ja heitti ne suureen Jumalan vihan kuurnaan.',
        20: 'Kuurna poljettiin kaupungin ulkopuolella, ja kuurnasta kuohui veri hevosten kuolaimiin asti, tuhannen kuudensadan stadionin päähän.',
    },
    15: {
        1: 'Näin toisen merkin taivaassa, suuren ja ihmeellisen: seitsemän enkeliä, joilla oli seitsemän viimeistä vitsausta, sillä niissä täyttyy Jumalan viha.',
        2: 'Näin kuin lasisen meren, tulella sekoitetun, ja niiden, jotka olivat saaneet voiton pedosta, sen kuvasta, sen merkistä ja sen nimen luvusta, seisovan lasisella merellä, ja heillä oli Jumalan sitrat.',
        3: 'He veisasivat Mooseksen, Jumalan palvelijan, virttä ja Karitsan virttä, sanoen: "Suuret ja ihmeelliset ovat tekosi, Herra Jumala, Kaikkivaltias. Vanhurskaat ja todet ovat tiesi, sinä pyhien kuningas.',
        4: 'Kuka ei pelkäisi sinua, Herra, ja ylistäisi nimeäsi? Sillä sinä yksin olet Pyhä, sillä kaikki kansat tulevat ja kumartuvat edessäsi, koska vanhurskaat tuomiosi ovat tulleet julki."',
        5: 'Sen jälkeen minä näin: todistuksen majan temppeli avattiin taivaassa.',
        6: 'Seitsemän enkeliä, joilla oli ne seitsemän vitsausta, lähti temppelistä puettuina puhtaisiin, hohtaviin pellavavaatteisiin ja vyötettyinä rinnoilta kultaisilla vöillä.',
        7: 'Yksi neljästä olennosta antoi seitsemälle enkelille seitsemän kultamaljaa täynnä Jumalan vihaa, hänen, joka elää iäisyyksien iäisyyksiin.',
        8: 'Temppeli tuli savua täyteen Jumalan kirkkaudesta ja hänen voimastaan, eikä kukaan voinut mennä sisälle temppeliin, ennen kuin seitsemän enkelin seitsemän vitsausta oli käynyt täytäntöön.',
    },
    16: {
        1: 'Kuulin suuren äänen temppelistä sanovan seitsemälle enkelille: "Menkää ja vuodattakaa seitsemän Jumalan vihan maljaa maan päälle."',
        2: 'Ensimmäinen lähti ja vuodatti maljansa maan päälle. Tuli pahoja ja kamalia paiseita niihin ihmisiin, joissa oli pedon merkki ja jotka kumarsivat sen kuvaa.',
        3: 'Toinen enkeli vuodatti maljansa mereen, ja se tuli vereksi, ikään kuin kuolleen vereksi. Jokainen elävä sielu kuoli, mitä meressä oli.',
        4: 'Kolmas enkeli vuodatti maljansa jokiin ja vesilähteisiin, ja ne tulivat vereksi.',
        5: 'Kuulin vesien enkelin sanovan: "Vanhurskas olet sinä, joka olet ja joka olit, kun näin olet tuominnut.',
        6: 'Sillä pyhien ja profeettojen verta he ovat vuodattaneet, ja verta sinä olet antanut heidän juotavakseen. Sen he ovat ansainneet."',
        7: 'Kuulin toisen alttarilta sanovan: "Totisesti, Herra Jumala, Kaikkivaltias, oikeat ja vanhurskaat ovat sinun tuomiosi."',
        8: 'Neljäs enkeli vuodatti maljansa aurinkoon, ja sille annettiin valta paahtaa ihmisiä tulella.',
        9: 'Ihmiset paahtuivat kovassa helteessä ja pilkkasivat Jumalan nimeä, hänen, jolla on vallassaan nämä vitsaukset, mutta he eivät tehneet parannusta, niin että olisivat antaneet hänelle kunnian.',
        10: 'Viides enkeli vuodatti maljansa pedon valtaistuimelle, ja sen valtakunta pimeni. He pureskelivat kielensä rikki tuskissaan',
        11: 'ja pilkkasivat taivaan Jumalaa tuskiensa ja paiseittensa tähden, mutta eivät tehneet parannusta teoistaan.',
        12: 'Kuudes enkeli vuodatti maljansa suureen Eufrat-virtaan, ja sen vesi kuivui, että tie valmistuisi auringon noususta tuleville kuninkaille.',
        13: '[Minä] näin lohikäärmeen suusta, pedon suusta ja väärän profeetan suusta lähtevän kolme saastaista henkeä, sammakon kaltaista.',
        14: 'Sillä ne ovat riivaajien henkiä, jotka tekevät merkkejä. Ne lähtevät maan ja koko maanpiirin kuningasten luo kokoamaan heitä sotaan Jumalan, Kaikkivaltiaan, suurena päivänä.',
        15: '– Katso, minä tulen kuin varas. Autuas joka valvoo ja pitää vaatteistaan vaarin, ettei kulkisi alastomana eikä hänen häpeäänsä nähtäisi! –',
        16: 'Ne kokosivat heidät siihen paikkaan, jonka nimi hepreaksi on Harmageddon.',
        17: 'Seitsemäs enkeli vuodatti maljansa ilmaan, ja temppelistä, valtaistuimelta, lähti suuri ääni, joka sanoi: "Se on tapahtunut."',
        18: 'Tuli salamoita, ääniä ja ukkosenjyrinää. Tuli suuri maanjäristys, niin ankara ja suuri maanjäristys, ettei sellaista ole ollut siitä asti, kun ihmisiä on ollut maan päällä.',
        19: 'Se suuri kaupunki meni kolmeen osaan, ja kansojen kaupungit luhistuivat. Suuri Babylon tuli muistetuksi Jumalan edessä, niin että hän antoi sille vihansa kiivauden viinimaljan.',
        20: 'Jokainen saari pakeni, eikä vuoria löydetty.',
        21: 'Suuria talentin painoisia rakeita satoi taivaalta ihmisten päälle, ja ihmiset pilkkasivat Jumalaa raesateen vitsauksen tähden, sillä vitsaus oli hyvin suuri.',
    },
    17: {
        1: 'Sitten tuli yksi niistä seitsemästä enkelistä, joilla oli seitsemän maljaa, ja puhui minulle sanoen: "Tule, näytän sinulle sen suuren porton tuomion, joka istuu paljojen vetten päällä,',
        2: 'hänet, jonka kanssa maan kuninkaat ovat haureutta harjoittaneet ja jonka haureuden viinistä maan asukkaat ovat juopuneet."',
        3: 'Hän vei minut Hengessä erämaahan. Siellä näin naisen istuvan helakanpunaisen pedon selässä. Peto oli täynnä pilkkaavia nimiä, ja sillä oli seitsemän päätä ja kymmenen sarvea.',
        4: 'Nainen oli puettu purppuraan ja helakanpunaan sekä koristeltu kullalla, jalokivillä ja helmillä ja piti kädessään kultaista maljaa, joka oli täynnä kauhistuksia ja hänen haureutensa saastaa.',
        5: 'Hänen otsaansa oli kirjoitettu nimi, salaisuus: "Suuri Babylon, maan porttojen ja kauhistusten äiti."',
        6: 'Näin naisen olevan juovuksissa pyhien verestä ja Jeesuksen todistajien verestä. Hänet nähdessäni ihmettelin suuresti.',
        7: 'Enkeli sanoi minulle: "Miksi ihmettelet? Sanon sinulle naisen salaisuuden ja sen pedon salaisuuden, joka häntä kantaa ja jolla on seitsemän päätä ja kymmenen sarvea.',
        8: 'Peto, jonka näit, on ollut, eikä sitä enää ole, mutta se on nouseva syvyydestä ja menevä kadotukseen. Ne maan päällä asuvat, joiden nimet eivät ole kirjoitettuja elämän kirjaan, aina maailman perustamisesta, ihmettelevät, kun he näkevät pedon, että se on ollut eikä sitä enää ole, vaikka se on.',
        9: 'Tässä on ymmärrys, jolla on viisaus: Seitsemän päätä ovat seitsemän vuorta, joiden päällä nainen istuu. Ne ovat myös seitsemän kuningasta.',
        10: 'Heistä viisi on kaatunut, yksi on, toinen ei ole vielä tullut, ja kun hän tulee, hänen pitää vähän aikaa pysyä.',
        11: 'Peto, joka on ollut ja jota ei enää ole, on itse kahdeksas, ja on yksi noista seitsemästä, ja menee kadotukseen.',
        12: 'Kymmenen sarvea, jotka näit, on kymmenen kuningasta, jotka eivät ole vielä saaneet kuninkuutta, mutta saavat vallan niin kuin kuninkaat yhdeksi hetkeksi pedon kanssa.',
        13: 'Näillä on yksi ja sama mieli, ja he antavat voimansa ja valtansa pedolle.',
        14: 'He sotivat Karitsaa vastaan, mutta Karitsa on voittava heidät, sillä hän on herrojen Herra ja kuningasten Kuningas. Kutsutut, valitut ja uskolliset voittavat hänen kanssaan."',
        15: 'Hän sanoi minulle: "Vedet, jotka näit siellä, missä portto istuu, ovat kansakuntia, väkijoukkoja, pakanoita ja kieliä.',
        16: 'Kymmenen sarvea, jotka näit, ja peto, ne vihaavat porttoa ja riisuvat hänet paljaaksi ja alastomaksi ja syövät hänen lihansa ja polttavat hänet tulessa.',
        17: 'Sillä Jumala on pannut heidän sydämeensä, että he täyttävät hänen ajatuksensa yksimielisesti, ja antavat kuninkuutensa pedolle, kunnes Jumalan sanat täyttyvät.',
        18: 'Nainen, jonka näit, on se suuri kaupunki, jolla on maan kuninkaitten kuninkuus."',
    },
    18: {
        1: 'Sen jälkeen näin tulevan taivaasta alas erään toisen enkelin, jolla oli suuri valta, ja maa valkeni hänen kirkkaudestaan.',
        2: 'Hän huusi kovaa suurella äänellä sanoen: "Luhistunut, luhistunut on suuri Babylon. Siitä on tullut riivaajien asuinpaikka ja kaikkien saastaisten henkien vankila ja kaikkien saastaisten ja vihattavien lintujen vankila.',
        3: 'Sillä hänen haureutensa vihan viiniä ovat kaikki kansat juoneet, ja maan kuninkaat ovat haureutta harjoittaneet hänen kanssaan, ja maan kauppiaat ovat rikastuneet hänen ylellisyytensä voimasta."',
        4: 'Sitten kuulin toisen äänen taivaasta sanovan: "Lähtekää siitä ulos, te minun kansani, ettette tulisi osallisiksi hänen synteihinsä ja saisi osaksenne hänen vitsauksiaan.',
        5: 'Sillä hänen syntinsä ulottuvat taivaaseen asti, ja Jumala on muistanut hänen rikoksensa.',
        6: 'Kostakaa hänelle sen mukaan, kuin hän on tehnyt teille, ja antakaa hänelle kaksinkertaisesti hänen teoistaan. Siihen maljaan, johon hän on kaatanut, kaatakaa te hänelle kaksin verroin.',
        7: "Niin paljon kuin hän on hankkinut itselleen kunniaa ja ylellisyyttä, niin paljon antakaa hänelle vaivaa ja surua. Koska hän sanoo sydämessään: 'Minä istun kuningattarena enkä ole leski enkä ole surua näkevä',",
        8: 'sen tähden hänen vitsauksensa tulevat yhtenä päivänä: kuolema, suru ja nälkä, ja hänet poltetaan tulessa, sillä väkivahva on Herra Jumala, joka hänet tuomitsee."',
        9: 'Maanpiirin kuninkaat, jotka harjoittivat hänen kanssaan haureutta ja elivät ylellisesti, itkevät ja valittavat häntä, kun näkevät hänen palonsa savun.',
        10: 'He seisovat loitolla kauhistuen hänen vaivaansa ja sanovat: "Voi, voi sinua, Babylon, sinä suuri kaupunki, sinä vahva kaupunki, sillä sinun tuomiosi tuli yhdessä hetkessä!"',
        11: 'Maanpiirin kauppiaat itkevät ja surevat häntä, kun kukaan ei enää osta heidän tavaraansa,',
        12: 'kaupaksi tuotua kultaa, hopeaa, jalokiviä, helmiä, pellavakangasta, purppuraa, silkkiä, helakanpunaa, kaikenlaista hajupuuta, kaikenlaisia norsunluuesineitä, kaikenlaisia kalleimmasta puusta, vaskesta, raudasta ja marmorista tehtyjä esineitä,',
        13: 'kanelia, hiusvoidetta, suitsuketta, hajuvoidetta, suitsutuspihkaa, viiniä, öljyä, ydinjauhoja, viljaa, karjaa, lampaita, hevosia, vaunuja, orjia ja ihmissieluja.',
        14: 'Hedelmät, joita sielusi himoitsi, ovat sinulta menneet, ja kaikki kalleutesi ja kimalluksesi ovat sinulta hävinneet, etkä löydä niitä enää koskaan.',
        15: 'Niiden kauppiaat, ne, jotka rikastuivat tästä kaupungista, seisovat loitolla kauhistuen hänen vaivaansa, itkien ja surren,',
        16: 'ja sanovat: "Voi, voi sitä suurta kaupunkia, joka oli puettu pellavaan, purppuraan ja helakanpunaan sekä koristeltu kullalla, jalokivillä ja helmillä, kun sellainen rikkaus tuhoutui yhdessä hetkessä!"',
        17: 'Kaikki laivurit, kaikki rannikkopurjehtijat, merimiehet ja kaikki merenkulkijat seisoivat loitolla',
        18: 'ja huusivat nähdessään hänen palonsa savun ja sanoivat: "Mikä on tämän suuren kaupungin kaltainen?"',
        19: 'He heittivät tomua päänsä päälle ja huusivat itkien ja surren ja sanoivat: "Voi, voi sitä suurta kaupunkia, jonka kalleuksista rikastuivat kaikki, joilla oli laivoja merellä, kun se yhdessä hetkessä tuhoutui!"',
        20: 'Riemuitse hänestä, taivas, ja pyhät ja apostolit ja profeetat, sillä Jumala on tuominnut hänet ja kostanut hänelle teidän tuomionne.',
        21: 'Väkivahva enkeli otti kiven, kuin suuren myllynkiven, ja heitti sen mereen sanoen: "Näin heitetään vauhdilla pois Babylon, se suuri kaupunki, eikä sitä enää löydetä."',
        22: 'Sinussa ei enää kuulla sitransoittajien ja laulajien, huilun- ja torvensoittajien ääntä, sinusta ei enää löydetä minkään ammatin taitajaa eikä sinussa kuulla enää myllyn ääntä.',
        23: 'Sinussa ei loista enää lampun valo. Sinussa ei kuulla enää huutoa yljälle eikä huutoa morsiamelle, sillä kauppiaasi olivat maan mahtavia, ja noituutesi eksytti kaikki kansat.',
        24: 'Ja hänestä on löydetty profeettojen ja pyhien veri ja kaikkien veri, jotka maan päällä ovat tapetut.',
    },
    19: {
        1: 'Sen jälkeen kuulin kuin kansan paljouden suuren äänen taivaassa sanovan: "Halleluja! Pelastus, kunnia, ylistys ja voima Herralle, Jumalallemme!',
        2: 'Sillä oikeat ja vanhurskaat ovat hänen tuomionsa, sillä hän on tuominnut suuren porton, joka turmeli maan haureudellaan, ja on kostanut hänen kätensä vuodattaman palvelijoidensa veren."',
        3: 'He sanoivat toisen kerran: "Halleluja!" Hänen savunsa nousee iäisyyksien iäisyyksiin asti.',
        4: 'Kaksikymmentä neljä vanhinta ja neljä olentoa lankesivat maahan ja kumartaen rukoilivat Jumalaa, joka valtaistuimella istuu, ja sanoivat: "Aamen, halleluja!"',
        5: 'Valtaistuimelta lähti ääni, joka sanoi: "Ylistäkää meidän Jumalaamme, kaikki hänen palvelijansa, te, jotka häntä pelkäätte, sekä pienet että suuret."',
        6: 'Kuulin kuin kansan paljouden äänen ja kuin paljojen vetten kohinan ja kuin suurten ukkosen jyrähdysten sanovan: "Halleluja! Sillä Herra, meidän Jumalamme, Kaikkivaltias, on ottanut kuninkuuden.',
        7: 'Iloitkaamme ja riemuitkaamme ja antakaamme kunnia hänelle, sillä Karitsan häät ovat tulleet, ja hänen vaimonsa on itsensä valmistanut.',
        8: 'Hänen annettiin pukeutua liinavaatteeseen, hohtavaan ja kirkkaaseen: liina on pyhien vanhurskaudet."',
        9: 'Hän sanoi minulle: "Kirjoita: Autuaat ne, jotka ovat kutsutut Karitsan hääaterialle!" Vielä hän sanoi minulle: "Nämä sanat ovat todet Jumalan sanat."',
        10: 'Silloin lankesin hänen jalkojensa juureen kumartaen rukoillakseni häntä. Mutta hän sanoi minulle: "Varo, ettet tee sitä. Olen sinun ja veljiesi työtoveri, niiden, joilla on Jeesuksen todistus. Kumartaen rukoile Jumalaa. Sillä Jeesuksen todistus on profetian henki."',
        11: '[Minä] näin taivaan avoinna. Ja katso: valkoinen hevonen, ja sen selässä istuvan nimi on Uskollinen ja Tosi, ja hän tuomitsee ja sotii vanhurskaudessa.',
        12: 'Hänen silmänsä olivat kuin tulen liekit, ja hänen päässään oli monta kruunua. Hänellä oli kirjoitettuna nimi, jota ei tiedä kukaan muu kuin hän itse,',
        13: 'ja hänellä oli yllään vereen kastettu viitta, ja nimi, jolla häntä kutsutaan, on Jumalan Sana.',
        14: 'Häntä seurasivat ratsastaen valkoisilla hevosilla taivaassa olevat sotajoukot puettuina valkoiseen ja puhtaaseen pellavaan.',
        15: 'Hänen suustaan lähtee terävä miekka hänen sillä lyödäkseen pakanakansoja. Hän on kaitseva heitä rautaisella valtikalla, ja hän polkee kaikkivaltiaan Jumalan vihan kiivauden viinikuurnan.',
        16: 'Hänellä on viitassa lanteillaan kirjoitettuna nimi: "Kuningasten Kuningas ja herrojen Herra."',
        17: 'Näin enkelin seisovan auringossa, ja hän huusi suurella äänellä sanoen kaikille keskitaivaalla lentäville linnuille: "Tulkaa, kokoontukaa suuren Jumalan aterialle',
        18: 'syömään kuningasten lihaa, sotapäälliköiden lihaa, mahtavien lihaa ja hevosten sekä niiden selässä istuvien lihaa ja kaikkien vapaitten ja orjien lihaa, sekä pienten että suurten."',
        19: 'Näin pedon, maan kuninkaat ja heidän sotajoukkonsa kokoontuneina sotiakseen hevosen selässä istuvaa vastaan ja hänen sotajoukkoaan vastaan.',
        20: 'Peto otettiin kiinni, ja sen kanssa väärä profeetta. Hän oli sen nähden tehnyt ihmetekonsa, joilla hän oli eksyttänyt ne, jotka olivat ottaneet pedon merkin, ja ne, jotka olivat kumartaneet sen kuvaa. Ne molemmat heitettiin tuliseen järveen, joka palaa rikkiä.',
        21: 'Muut saivat surmansa hevosen selässä istuvan miekasta, joka lähti hänen suustaan, ja kaikki linnut tulivat ravituiksi heidän lihastaan.',
    },
    20: {
        1: 'Näin tulevan taivaasta alas enkelin, jolla oli syvyyden avain ja suuri kahle kädessään.',
        2: 'Hän otti kiinni lohikäärmeen, sen vanhan käärmeen, joka on perkele ja saatana, ja sitoi hänet tuhanneksi vuodeksi',
        3: 'ja heitti hänet syvyyteen ja sulki ja lukitsi sen sinetillä hänen jälkeensä, ettei hän enää villitsisi pakanoita, siihen asti kunnes ne tuhat vuotta ovat kuluneet loppuun. Sen jälkeen hänet pitää päästää irti vähäksi aikaa.',
        4: 'Näin valtaistuimia, ja he istuivat niillä, ja heille annettiin tuomiovalta. Näin niiden sielut, jotka olivat teloitetut Jeesuksen todistuksen ja Jumalan sanan tähden, ja niiden, jotka eivät olleet kumartaneet petoa, eivät sen kuvaa eivätkä ottaneet sen merkkiä otsaansa eivätkä käteensä. He elivät ja hallitsivat Kristuksen kanssa tuhat vuotta.',
        5: 'Muut kuolleet eivät alkaneet elää, ennen niiden tuhannen vuoden päättymistä. Tämä on ensimmäinen ylösnousemus.',
        6: 'Autuas ja pyhä on se, jolla on osa ensimmäisessä ylösnousemuksessa. Heihin toisella kuolemalla ei ole valtaa, vaan he tulevat olemaan Jumalan ja Kristuksen pappeja ja hallitsevat hänen kanssaan tuhat vuotta.',
        7: 'Kun ne tuhat vuotta ovat lopullisesti päättymässä, päästetään saatana vankilastaan,',
        8: 'ja hän lähtee villitsemään maan neljällä kulmalla olevia kansoja, Googia ja Maagogia, kootakseen heidät sotaan, ja niiden luku on kuin meren hiekka.',
        9: 'He nousevat yli maan avaruuden ja piirittävät pyhien leirin ja sen rakastetun kaupungin. Mutta tuli lankeaa taivaasta ja syö heidät.',
        10: 'Perkele, heidän villitsijänsä, heitettiin tuli- ja rikkijärveen, jossa myös peto ja väärä profeetta ovat, ja heitä vaivataan yötä päivää iäisyyksien iäisyyksiin.',
        11: 'Näin suuren, valkoisen valtaistuimen ja sillä istuvan, jonka kasvoja maa ja taivas pakenivat, eikä niille löytynyt paikkaa.',
        12: 'Näin kuolleet, suuret ja pienet, seisomassa valtaistuimen edessä, ja kirjat avattiin, ja avattiin toinen kirja, joka on elämän kirja, ja kuolleet tuomittiin sen perusteella, mitä kirjoihin oli kirjoitettu, tekojensa mukaan.',
        13: 'Meri antoi ne kuolleet, jotka siinä olivat, ja kuolema ja helvetti antoivat ne kuolleet, jotka niissä olivat, ja heidät tuomittiin, kukin tekojensa mukaan.',
        14: 'Kuolema ja helvetti heitettiin tuliseen järveen. Tämä on toinen kuolema, tulinen järvi.',
        15: 'Joka ei ollut elämän kirjaan kirjoitettu, heitettiin tuliseen järveen.',
    },
    21: {
        1: 'Näin uuden taivaan ja uuden maan, sillä ensimmäinen taivas ja ensimmäinen maa ovat kadonneet, eikä merta enää ole.',
        2: 'Minä, Johannes, näin pyhän kaupungin, uuden Jerusalemin, laskeutuvan alas taivaasta Jumalan luota, valmistettuna kuin morsian, miehelleen kaunistettuna.',
        3: 'Kuulin suuren äänen valtaistuimelta sanovan: "Katso, Jumalan maja ihmisten keskellä! Hän on asuva heidän keskellään, ja he ovat hänen kansojaan, ja Jumala itse on oleva heidän kanssaan, heidän Jumalansa.',
        4: 'Hän on pyyhkivä pois kaikki kyyneleet heidän silmistään, eikä kuolemaa ole enää oleva, ei murhetta, ei itkua eikä kipua ole enää oleva, sillä entinen on mennyt pois."',
        5: 'Valtaistuimella istuva sanoi: "Katso, uudeksi minä teen kaikki." Sitten hän sanoi: "Kirjoita, sillä nämä sanat ovat todet ja luotettavat."',
        6: 'Hän sanoi minulle: "Se on tapahtunut. Minä olen A ja O, alku ja loppu. Minä annan janoavalle elämän veden lähteestä lahjaksi.',
        7: 'Joka voittaa, on perivä kaiken, ja olen oleva hänelle Jumala, ja hän on oleva minulle poika.',
        8: 'Mutta pelkurien, epäuskoisten, saastaisten, murhaajien, huorintekijöiden, noitien, epäjumalanpalvelijoiden ja kaikkien valehtelijoiden osa on oleva siinä järvessä, joka palaa tulta ja rikkiä. Tämä on toinen kuolema."',
        9: 'Sitten tuli yksi niistä seitsemästä enkelistä, joilla oli seitsemän maljaa täynnä seitsemää viimeistä vitsausta, ja puhui kanssani sanoen: "Tule, näytän sinulle morsiamen, Karitsan vaimon."',
        10: 'Hän vei minut Hengessä suurelle ja korkealle vuorelle ja näytti minulle pyhän kaupungin, Jerusalemin, joka laskeutui alas taivaasta Jumalan luota,',
        11: 'ja siinä oli Jumalan kirkkaus. Sen hohto oli kaikkein kalleimman kiven kaltainen, kuin kristallinkirkas jaspiskivi.',
        12: 'Sillä oli suuri ja korkea muuri, jossa oli kaksitoista porttia ja porteilla kaksitoista enkeliä, ja niihin oli kirjoitettu nimiä, ja ne ovat Israelin lasten kahdentoista sukukunnan nimet.',
        13: 'Idässä oli kolme porttia ja pohjoisessa kolme porttia ja etelässä kolme porttia ja lännessä kolme porttia.',
        14: 'Kaupungin muurilla oli kaksitoista perustusta, ja niissä Karitsan kahdentoista apostolin kaksitoista nimeä.',
        15: 'Sillä, joka minulle puhui, oli kultainen ruoko mitatakseen kaupungin, sen portit ja sen muurin.',
        16: 'Kaupunki oli neliskulmainen, ja sen pituus oli yhtä suuri kuin sen leveys. Hän mittasi mittakepillä kaupungin: se oli kaksitoista tuhatta stadionia. Sen pituus, leveys ja korkeus olivat yhtä suuret.',
        17: 'Hän mittasi myös sen muurin: se oli sata neljäkymmentä neljä kyynärää ihmismitan mukaan, joka on enkelinkin mitta.',
        18: 'Sen muuri oli rakennettu jaspiksesta, ja kaupunki oli puhdasta kultaa, puhtaan lasin kaltaista.',
        19: 'Kaupungin muurin perustukset oli koristeltu kaikenlaisilla kalliilla kivillä. Ensimmäinen perustus oli jaspis, toinen safiiri, kolmas kalkedon, neljäs smaragdi,',
        20: 'viides sardonyks, kuudes sardion, seitsemäs krysoliitti, kahdeksas berylli, yhdeksäs topaasi, kymmenes krysoprasi, yhdestoista hyasintti ja kahdestoista ametisti.',
        21: 'Kaksitoista porttia oli kaksitoista helmeä. Jokainen portti oli yhdestä helmestä. Kaupungin katu oli puhdasta kultaa, kuin läpinäkyvää lasia.',
        22: 'Mutta temppeliä en siinä nähnyt, sillä Herra Jumala, Kaikkivaltias, on sen temppeli, ja Karitsa.',
        23: 'Eikä kaupunki tarvitse valokseen aurinkoa eikä kuuta, sillä Jumalan kirkkaus valaisee sen, ja sen lamppu on Karitsa.',
        24: 'Autuaat pakanat vaeltavat sen valossa, ja maan kuninkaat vievät sinne kunniansa ja kalleutensa.',
        25: 'Sen portteja ei suljeta päivällä, eikä siellä ole yötä,',
        26: 'ja sinne viedään kansojen kunnia ja kalleudet.',
        27: 'Sinne ei mene mitään epäpyhää, ei ketään kauhistusten eikä valheiden tekijää, vaan ainoastaan ne, jotka ovat kirjoitetut Karitsan elämänkirjaan.',
    },
    22: {
        1: 'Hän näytti minulle elämän veden virran, joka kirkkaana kuin kristalli lähtee Jumalan ja Karitsan valtaistuimesta.',
        2: 'Keskellä sen katua ja virran molemmilla puolilla oli elämän puu, joka kantoi kahdettoista hedelmät, antaen joka kuukausi hedelmänsä, ja puun lehdet ovat kansojen tervehtymistä varten.',
        3: 'Eikä mitään kirousta ole enää oleva. Ja Jumalan ja Karitsan valtaistuin on siellä oleva, ja hänen palvelijansa palvelevat häntä',
        4: 'ja näkevät hänen kasvonsa, ja hänen nimensä on heidän otsallaan.',
        5: 'Eikä siellä ole yötä, eivätkä he tarvitse lampun valoa eivätkä auringon valoa, sillä Herra Jumala on valaiseva heitä, ja he hallitsevat iäisyyksien iäisyyksiin.',
        6: 'Hän sanoi minulle: "Nämä sanat ovat luotettavat ja todet, ja Herra, profeettojen henkien Jumala, on lähettänyt enkelinsä näyttämään palvelijoilleen, mitä pian täytyy tapahtua.',
        7: 'Katso, minä tulen pian. Autuas se, joka ottaa vaarin tämän kirjan profetian sanoista!"',
        8: 'Minä, Johannes, olen se, joka olen tämän nähnyt ja kuullut. Kun olin sen kuullut ja nähnyt, lankesin maahan kumartuakseni sen enkelin jalkojen eteen, joka tämän minulle näytti.',
        9: 'Mutta hän sanoi minulle: "Varo, ettet sitä tee. Minä olen sinun ja veljiesi, profeettojen, työtoveri, ja niiden, jotka ottavat tämän kirjan sanoista vaarin. Rukoile kumartaen Jumalaa."',
        10: 'Sitten hän sanoi minulle: "Älä sinetöi tämän kirjan profetian sanoja, sillä aika on lähellä.',
        11: 'Vääryyden tekijä tehköön edelleen vääryyttä, ja saastainen saastukoon edelleen, ja vanhurskas tehköön edelleen vanhurskautta, ja pyhä pyhittyköön edelleen.',
        12: 'Katso, tulen pian, ja palkkani on mukanani maksaakseni kullekin hänen tekojensa mukaan.',
        13: 'Minä olen A ja O, ensimmäinen ja viimeinen, alku ja loppu.',
        14: 'Autuaat ne, jotka pitävät hänen käskynsä, että heillä olisi valta elämän puuhun ja valta käydä porteista sisälle kaupunkiin!',
        15: 'Ulkopuolella ovat koirat, noidat, huorintekijät, murhaajat, epäjumalanpalvelijat ja kaikki, jotka rakastavat ja tekevät valhetta.',
        16: 'Minä, Jeesus, lähetin enkelini todistamaan näitä teille seurakunnissa. Minä olen Daavidin juurivesa ja hänen sukuaan, kirkas tähti ja aamutähti.',
        17: 'Henki ja morsian sanovat: "Tule!" Joka kuulee, sanokoon: "Tule!" Joka janoaa, tulkoon, ja joka tahtoo, ottakoon elämän vettä lahjaksi.',
        18: 'Minä todistan jokaiselle, joka tämän kirjan profetian sanat kuulee: Jos joku panee niihin jotakin lisää, Jumala panee hänen päälleen ne vitsaukset, jotka ovat kirjoitetut tähän kirjaan.',
        19: 'Jos joku taas ottaa pois jotakin tämän profetian kirjan sanoista, niin Jumala ottaa pois hänen osansa elämän kirjaan, pyhään kaupunkiin ja siihen, mitä tähän kirjaan on kirjoitettu.',
        20: 'Hän, joka näitä todistaa, sanoo: "Totisesti, tulen pian." Aamen, niin, tule, Herra Jeesus!',
        21: 'Herramme Jeesuksen armo on teidän kaikkien kanssa. Aamen.',
    },
}
